const contentPlaceholderPages = ['stories-resources', 'articles'];
if (contentPlaceholderPages.some((page) => isPage(page))) {
  const banner = document.querySelector('.page-banner');
  if (banner) {
    banner.insertAdjacentHTML('afterbegin', '<p class="content-status">Content preview · Stories, articles, and social integrations will be published after the website launch.</p>');
  }
}

const form = document.querySelector('#inquiry-form');
if (form) {
  form.addEventListener('submit', (event) => {
    event.preventDefault();
    const response = form.querySelector('.form-response');
    if (!form.checkValidity()) {
      form.reportValidity();
      return;
    }
    response.textContent = 'Thank you. Your inquiry is ready to be sent to the Dr Santi’s Story team.';
    form.reset();
  });
}

document.addEventListener('submit', (event) => {
  const ritualForm = event.target.closest('#reading-ritual-form');
  if (!ritualForm) return;
  event.preventDefault();
  if (!ritualForm.checkValidity()) {
    ritualForm.reportValidity();
    return;
  }
  ritualForm.querySelector('.ritual-response').textContent = ritualForm.querySelector('.ritual-response').dataset.response;
  window.open('https://raw.githubusercontent.com/mdarielfadli-byte/dr-santi-story/main/assets/7-days-reading-ritual.pdf', '_blank', 'noopener');
  ritualForm.reset();
});

document.addEventListener('input', (event) => {
  const phone = event.target.closest('#reading-ritual-form input[name="whatsapp"]');
  if (!phone) return;
  const value = phone.value.replace(/[^\d+]/g, '');
  if (value.startsWith('08')) phone.value = `+62${value.slice(1)}`;
  else if (value.startsWith('62')) phone.value = `+${value}`;
  else phone.value = value;
});
